INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('COP','published','{"ticker":"COP","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.conocophillips.com/news-media/","description":"Independent exploration and production company with a diversified portfolio of oil, natural gas, LNG, and oil-sands assets.","lede":"CONOCOPHILLIPS earns owner value through commodity sales determined by production volumes, realizations, transportation, royalties, taxes, and fiscal terms. The three questions that matter most are volumes, mix, decline, benchmark prices, differentials, and downtime, cost, schedule, synergies, plateau, reserves, and breakeven, operating cost, sustaining capital, taxes, debt, dividends, and repurchases.","sells":"Crude oil, natural gas, natural gas liquids, LNG interests, and bitumen.","revenueModel":"Commodity sales determined by production volumes, realizations, transportation, royalties, taxes, and fiscal terms.","opportunity":"Portfolio high-grading, LNG exposure, project execution, and productivity can improve mid-cycle free cash flow.","mustGoRight":"Acquisitions and projects must deliver, decline and cost must remain controlled, and capital returns must be funded at conservative prices.","editorNote":"Treat the claimed advantage—a diversified resource base, low-cost inventory, operating scale, and capital discipline can support cycle resilience.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["A diversified resource base, low-cost inventory, operating scale, and capital discipline can support cycle resilience.","Portfolio high-grading, LNG exposure, project execution, and productivity can improve mid-cycle free cash flow.","Visible progress in production & realizations and project & acquisition returns can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Commodity prices can weaken the owner outcome; monitor oil, gas, lng, differentials, hedging, and fiscal terms.","Reservoir and project execution can weaken the owner outcome; monitor reserves, decline, wells, cost, schedule, and production.","Policy and liabilities can weaken the owner outcome; monitor emissions, methane, decommissioning, tax, litigation, and host-country action.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if portfolio additions fail to earn adequate mid-cycle returns and sustaining capital or liabilities consume distributable cash.","financialDrivers":[{"label":"PRODUCTION & REALIZATIONS","value":"Primary owner KPI","detail":"volumes, mix, decline, benchmark prices, differentials, and downtime"},{"label":"PROJECT & ACQUISITION RETURNS","value":"Primary owner KPI","detail":"cost, schedule, synergies, plateau, reserves, and breakeven"},{"label":"MID-CYCLE CASH","value":"Primary owner KPI","detail":"operating cost, sustaining capital, taxes, debt, dividends, and repurchases"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Commodity prices","level":"High","text":"Commodity prices can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"oil, gas, LNG, differentials, hedging, and fiscal terms"},{"title":"Reservoir and project execution","level":"High","text":"Reservoir and project execution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"reserves, decline, wells, cost, schedule, and production"},{"title":"Policy and liabilities","level":"High","text":"Policy and liabilities can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"emissions, methane, decommissioning, tax, litigation, and host-country action"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"PRODUCTION & REALIZATIONS","text":"Track volumes, mix, decline, benchmark prices, differentials, and downtime and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"PROJECT & ACQUISITION RETURNS","text":"Track cost, schedule, synergies, plateau, reserves, and breakeven and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"MID-CYCLE CASH","text":"Track operating cost, sustaining capital, taxes, debt, dividends, and repurchases and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies production & realizations?","What would cause project & acquisition returns to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in mid-cycle cash?","Where does CONOCOPHILLIPS have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"ExxonMobil Holdings Corp, CHEVRON CORP, EOG RESOURCES INC, OCCIDENTAL PETROLEUM CORP, DEVON ENERGY CORP/DE, HES","comparables":[{"name":"ExxonMobil Holdings Corp","ticker":"XOM","ownership":"Public","relationship":"Operating and valuation reference for COP","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with COP.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0002115436&owner=exclude"},{"name":"CHEVRON CORP","ticker":"CVX","ownership":"Public","relationship":"Operating and valuation reference for COP","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with COP.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000093410&owner=exclude"},{"name":"EOG RESOURCES INC","ticker":"EOG","ownership":"Public","relationship":"Operating and valuation reference for COP","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with COP.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000821189&owner=exclude"},{"name":"OCCIDENTAL PETROLEUM CORP","ticker":"OXY","ownership":"Public","relationship":"Operating and valuation reference for COP","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with COP.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000797468&owner=exclude"},{"name":"DEVON ENERGY CORP/DE","ticker":"DVN","ownership":"Public","relationship":"Operating and valuation reference for COP","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with COP.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001090012&owner=exclude"},{"name":"HES","ticker":"HES","ownership":"Public","relationship":"Operating and valuation reference for COP","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with COP.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=HES&owner=exclude"}],"sources":[{"title":"COP SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0001163165&owner=exclude","excerpt":"CONOCOPHILLIPS filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"COP annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001163165&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"COP quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001163165&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"COP proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001163165&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"COP investor relations","meta":"Company primary materials","href":"https://www.conocophillips.com/investor-relations/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"COP official newsroom","meta":"Company announcements","href":"https://www.conocophillips.com/news-media/","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}],"evidenceReview":{"reviewedAt":"August 2, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001163165&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001163165&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001163165&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001163165&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://www.conocophillips.com/investor-relations/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;
