INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('COST','published','{"ticker":"COST","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://investor.costco.com/news/default.aspx","description":"Membership warehouse retailer offering limited-SKU merchandise, fuel, pharmacy, optical, travel, food services, and e-commerce.","lede":"Costco uses membership economics, purchasing scale, high inventory turns, and low markups to reinforce customer trust and renewal. The key owner question is how much growth and margin are already capitalized.","sells":"Groceries, general merchandise, fuel, pharmacy, optical, hearing aids, travel, food court products, and memberships.","revenueModel":"Warehouse and e-commerce product sales plus recurring membership fees, with low merchandise margins supporting value and renewal.","opportunity":"Global warehouse expansion, household penetration, executive membership, and ancillary services can compound traffic and fee income.","mustGoRight":"Renewal and traffic must remain high, price trust must be protected, new warehouses must earn strong returns, and labor and sourcing costs must be managed.","editorNote":"Membership fees are economically central, but warehouse productivity, renewal, and capital returns determine whether the model can support its valuation.","bullTitle":"What can compound owner value","bull":["Membership creates recurring revenue and aligns the company with customer value.","Scale and limited assortment support purchasing power and inventory turns.","High renewal and traffic reinforce a durable retail flywheel.","International warehouse expansion extends the runway."],"bearTitle":"What can impair the thesis","bear":["A premium valuation raises sensitivity to modest execution misses.","Thin merchandise margins leave limited room for cost shocks.","Fuel and foreign exchange can distort reported sales.","Rapid expansion could weaken site selection or member economics."],"thesisBreaker":"The thesis breaks if renewal and traffic weaken while new warehouses earn lower returns and price investment prevents membership growth from converting to cash.","financialDrivers":[{"label":"COMPARABLE SALES","value":"Traffic and ticket","detail":"Transactions, average ticket, fuel, FX, e-commerce, and category mix"},{"label":"MEMBERSHIP","value":"Renewal and fee income","detail":"Paid households, executive mix, renewal, fee changes, and deferred revenue"},{"label":"WAREHOUSE RETURNS","value":"Unit growth","detail":"Openings, mature sales, site economics, cannibalization, and capital cost"},{"label":"MERCHANDISE MARGIN","value":"Value discipline","detail":"Markups, shrink, freight, wage, sourcing, and mix"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle."},{"label":"PER-SHARE VALUE","value":"Cash conversion","detail":"Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count."}],"risks":[{"title":"Valuation expectations","level":"High","text":"Strong execution may already be embedded in price.","signal":"Implied growth, margin assumptions, and free-cash-flow yield"},{"title":"Cost and price investment","level":"Medium","text":"Wage, freight, shrink, and sourcing costs can pressure thin margins.","signal":"Gross margin, SG&A, price gaps, and wage expense"},{"title":"Expansion execution","level":"Medium","text":"New locations may have weaker density or returns.","signal":"New-unit sales, cannibalization, payback, and membership ramp"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting risk","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"Renewal and traffic","text":"Track behavior rather than fee income alone.","impact":"BULL CASE"},{"title":"New warehouse cohorts","text":"Compare mature productivity and returns across regions.","impact":"NEUTRAL"},{"title":"Margin versus value","text":"Watch for margin gains that risk weakening customer trust.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.","impact":"NEUTRAL"}],"questions":["What return does the next warehouse cohort earn?","How sensitive is renewal to membership pricing?","How much margin can expand without weakening price leadership?","What growth and terminal economics are implied by valuation?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?"],"competitors":"Walmart, BJ''s Wholesale Club, Amazon, Target, Kroger, hard discounters, and regional grocers.","comparables":[{"name":"Walmart","ticker":"WMT","ownership":"Public","relationship":"Operating and valuation reference for COST","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with COST.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=WMT&owner=exclude"},{"name":"BJ''s Wholesale Club","ticker":"BJ","ownership":"Public","relationship":"Operating and valuation reference for COST","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with COST.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=BJ&owner=exclude"},{"name":"Target","ticker":"TGT","ownership":"Public","relationship":"Operating and valuation reference for COST","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with COST.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=TGT&owner=exclude"},{"name":"Amazon","ticker":"AMZN","ownership":"Public","relationship":"Operating and valuation reference for COST","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with COST.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=AMZN&owner=exclude"},{"name":"Kroger","ticker":"KR","ownership":"Public","relationship":"Operating and valuation reference for COST","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with COST.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=KR&owner=exclude"},{"name":"Dollar General","ticker":"DG","ownership":"Public","relationship":"Operating and valuation reference for COST","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with COST.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=DG&owner=exclude"}],"sources":[{"title":"COST SEC filing library","meta":"SEC EDGAR · Primary source","href":"https://www.sec.gov/edgar/browse/?CIK=909832&owner=exclude","excerpt":"The SEC filing record provides COST''s annual, quarterly, current, proxy, ownership, and registration disclosures."},{"title":"COST annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=909832&type=10-K&owner=exclude&count=40","excerpt":"Annual filings describe the business, segments, competition, audited financial statements, commitments, controls, and material risks."},{"title":"COST quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=909832&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion between annual reports."},{"title":"COST proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=909832&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"COST investor relations","meta":"Company primary materials","href":"https://investor.costco.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"COST official newsroom","meta":"Company announcements","href":"https://investor.costco.com/news/default.aspx","excerpt":"Official product, operational, leadership, partnership, and corporate announcements used as management assertions pending independent verification."}],"evidenceReview":{"reviewedAt":"August 1, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000909832&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000909832&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000909832&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000909832&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://investor.costco.com/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;
