INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('CSCO','published','{"ticker":"CSCO","reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://newsroom.cisco.com/","description":"Networking and infrastructure-technology company spanning switching, routing, wireless, security, observability, collaboration, and related services.","lede":"Cisco is shifting from hardware cycles toward software, subscriptions, security, and observability while defending the installed networking base through an AI data-center transition.","sells":"Enterprise and service-provider networking, wireless, security, observability, collaboration, support, software, and services.","revenueModel":"Product sales plus subscriptions, licenses, support, maintenance, and usage-based software services.","opportunity":"AI clusters, enterprise network renewal, security consolidation, and Splunk observability can deepen recurring relationships across the installed base.","mustGoRight":"AI networking must convert to revenue, Splunk must integrate without attrition, security relevance must improve, and recurring growth must offset hardware volatility.","editorNote":"Separate order and backlog normalization from true end-demand, and track recurring annualized revenue plus organic growth after acquisitions.","bullTitle":"What can compound owner value","bull":["A vast installed base provides distribution and upgrade opportunities.","AI infrastructure requires high-speed networking and observability.","Subscriptions and support add recurring cash flow.","Splunk can connect security, telemetry, and operations."],"bearTitle":"What can impair the thesis","bear":["Arista and hyperscaler architectures pressure data-center share.","Enterprise hardware demand is cyclical and backlog can distort growth.","Security remains crowded and rapidly changing.","Large acquisitions add integration and leverage risk."],"thesisBreaker":"The thesis breaks if Cisco loses strategic networking relevance in AI and cloud environments while software and Splunk growth cannot offset hardware share loss and acquisition costs.","financialDrivers":[{"label":"NETWORKING","value":"Orders and share","detail":"Campus, data center, routing, wireless, price, backlog, and product transitions"},{"label":"AI INFRASTRUCTURE","value":"New demand","detail":"Ethernet wins, optics, systems, customer concentration, and recognized revenue"},{"label":"SECURITY / OBSERVABILITY","value":"Platform growth","detail":"Splunk retention, ARR, cross-sell, product integration, and competition"},{"label":"RECURRING REVENUE","value":"Visibility","detail":"Subscriptions, support, remaining obligations, renewals, and net retention"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle."},{"label":"PER-SHARE VALUE","value":"Cash conversion","detail":"Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count."}],"risks":[{"title":"Cloud and AI architecture","level":"High","text":"Alternative vendors and custom designs can reduce Cisco content.","signal":"Market share, design wins, cloud deployments, and pricing"},{"title":"Acquisition integration","level":"High","text":"Splunk integration may cause attrition or delayed synergies.","signal":"ARR, renewals, employee retention, restructuring, and margins"},{"title":"Hardware cycle","level":"Medium","text":"Orders, backlog, inventory, and channel conditions can swing sharply.","signal":"Product orders, backlog, lead times, distributor inventory, and cancellations"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting risk","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"AI networking revenue","text":"Verify deployments and recognized revenue across customers.","impact":"BULL CASE"},{"title":"Splunk retention","text":"Track ARR, renewals, product investment, and cross-sell.","impact":"NEUTRAL"},{"title":"Core share","text":"Compare campus and data-center performance with specialist competitors.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.","impact":"NEUTRAL"}],"questions":["What portion of AI pipeline has converted to revenue?","Is Splunk retaining customers and innovation velocity?","How much recurring revenue is economically subscription-like?","Where is Cisco gaining or losing network share?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?"],"competitors":"Arista Networks, Hewlett Packard Enterprise, Juniper, Palo Alto Networks, Fortinet, cloud providers, and open networking systems.","comparables":[{"name":"Arista Networks","ticker":"ANET","ownership":"Public","relationship":"Operating and valuation reference for CSCO","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with CSCO.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=ANET&owner=exclude"},{"name":"Hewlett Packard Enterprise","ticker":"HPE","ownership":"Public","relationship":"Operating and valuation reference for CSCO","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with CSCO.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=HPE&owner=exclude"},{"name":"Palo Alto Networks","ticker":"PANW","ownership":"Public","relationship":"Operating and valuation reference for CSCO","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with CSCO.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=PANW&owner=exclude"},{"name":"Fortinet","ticker":"FTNT","ownership":"Public","relationship":"Operating and valuation reference for CSCO","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with CSCO.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=FTNT&owner=exclude"},{"name":"IBM","ticker":"IBM","ownership":"Public","relationship":"Operating and valuation reference for CSCO","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with CSCO.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=IBM&owner=exclude"},{"name":"Broadcom","ticker":"AVGO","ownership":"Public","relationship":"Operating and valuation reference for CSCO","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with CSCO.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=AVGO&owner=exclude"}],"sources":[{"title":"CSCO SEC filing library","meta":"SEC EDGAR · Primary source","href":"https://www.sec.gov/edgar/browse/?CIK=858877&owner=exclude","excerpt":"The SEC filing record provides CSCO''s annual, quarterly, current, proxy, ownership, and registration disclosures."},{"title":"CSCO annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=858877&type=10-K&owner=exclude&count=40","excerpt":"Annual filings describe the business, segments, competition, audited financial statements, commitments, controls, and material risks."},{"title":"CSCO quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=858877&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion between annual reports."},{"title":"CSCO proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=858877&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"CSCO investor relations","meta":"Company primary materials","href":"https://investor.cisco.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"CSCO official newsroom","meta":"Company announcements","href":"https://newsroom.cisco.com/","excerpt":"Official product, operational, leadership, partnership, and corporate announcements used as management assertions pending independent verification."}],"evidenceReview":{"reviewedAt":"August 1, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000858877&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000858877&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000858877&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000858877&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://investor.cisco.com/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;
