INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('ETN','published','{"ticker":"ETN","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.eaton.com/us/en-us/company/news-insights.html","description":"Electrical and industrial power-management company serving data centers, utilities, aerospace, vehicles, buildings, and machinery.","lede":"EATON PLC earns owner value through engineered equipment, component, project, aftermarket, and service sales through direct and distributor channels. The three questions that matter most are orders, data centers, utilities, commercial projects, lead times, and price, factory ramps, utilization, productivity, mix, labor, and materials, build rates, aftermarket, content, electrification, and operating margin.","sells":"Switchgear, breakers, power distribution, backup power, connectors, hydraulics, aerospace systems, and vehicle components.","revenueModel":"Engineered equipment, component, project, aftermarket, and service sales through direct and distributor channels.","opportunity":"Data centers, grid modernization, electrification, aerospace recovery, and reshoring can drive organic growth.","mustGoRight":"Capacity expansion must convert backlog without quality or cost issues, pricing must hold, and acquisitions must earn returns.","editorNote":"Treat the claimed advantage—installed distribution, engineering, qualification, and scarce electrical capacity can support pricing and backlog.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Installed distribution, engineering, qualification, and scarce electrical capacity can support pricing and backlog.","Data centers, grid modernization, electrification, aerospace recovery, and reshoring can drive organic growth.","Visible progress in electrical backlog and capacity & margin can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Cycle and backlog quality can weaken the owner outcome; monitor cancellations, project timing, book-to-bill, lead times, and pricing.","Capacity execution can weaken the owner outcome; monitor factory cost, labor, suppliers, quality, and utilization.","Competition and substitution can weaken the owner outcome; monitor price, specification, alternative technology, and share.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if electrical capacity additions meet a demand slowdown and backlog fails to convert into durable cash returns.","financialDrivers":[{"label":"ELECTRICAL BACKLOG","value":"Primary owner KPI","detail":"orders, data centers, utilities, commercial projects, lead times, and price"},{"label":"CAPACITY & MARGIN","value":"Primary owner KPI","detail":"factory ramps, utilization, productivity, mix, labor, and materials"},{"label":"AEROSPACE & VEHICLE","value":"Primary owner KPI","detail":"build rates, aftermarket, content, electrification, and operating margin"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Cycle and backlog quality","level":"High","text":"Cycle and backlog quality can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"cancellations, project timing, book-to-bill, lead times, and pricing"},{"title":"Capacity execution","level":"High","text":"Capacity execution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"factory cost, labor, suppliers, quality, and utilization"},{"title":"Competition and substitution","level":"High","text":"Competition and substitution can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"price, specification, alternative technology, and share"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"ELECTRICAL BACKLOG","text":"Track orders, data centers, utilities, commercial projects, lead times, and price and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"CAPACITY & MARGIN","text":"Track factory ramps, utilization, productivity, mix, labor, and materials and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"AEROSPACE & VEHICLE","text":"Track build rates, aftermarket, content, electrification, and operating margin and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies electrical backlog?","What would cause capacity & margin to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in aerospace & vehicle?","Where does EATON PLC have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"GE Vernova Inc., HUBBELL INC, ROCKWELL AUTOMATION, INC, EMERSON ELECTRIC CO, Parker-Hannifin Corp, Vertiv Holdings Co","comparables":[{"name":"GE Vernova Inc.","ticker":"GEV","ownership":"Public","relationship":"Operating and valuation reference for ETN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ETN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001996810&owner=exclude"},{"name":"HUBBELL INC","ticker":"HUBB","ownership":"Public","relationship":"Operating and valuation reference for ETN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ETN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000048898&owner=exclude"},{"name":"ROCKWELL AUTOMATION, INC","ticker":"ROK","ownership":"Public","relationship":"Operating and valuation reference for ETN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ETN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001024478&owner=exclude"},{"name":"EMERSON ELECTRIC CO","ticker":"EMR","ownership":"Public","relationship":"Operating and valuation reference for ETN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ETN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000032604&owner=exclude"},{"name":"Parker-Hannifin Corp","ticker":"PH","ownership":"Public","relationship":"Operating and valuation reference for ETN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ETN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000076334&owner=exclude"},{"name":"Vertiv Holdings Co","ticker":"VRT","ownership":"Public","relationship":"Operating and valuation reference for ETN","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ETN.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001674101&owner=exclude"}],"sources":[{"title":"ETN SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0001551182&owner=exclude","excerpt":"Eaton Corp plc filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"ETN annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001551182&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"ETN quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001551182&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"ETN proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001551182&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"ETN investor relations","meta":"Company primary materials","href":"https://www.eaton.com/us/en-us/company/investor-relations.html","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"ETN official newsroom","meta":"Company announcements","href":"https://www.eaton.com/us/en-us/company/news-insights.html","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}],"evidenceReview":{"reviewedAt":"August 2, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001551182&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001551182&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001551182&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001551182&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://www.eaton.com/us/en-us/company/investor-relations.html","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;
